WITH valid AS (SELECT id, full_name, email, manager_id, job_title, hire_date, CASE WHEN level = 'L5' THEN 1 ELSE 0 END AS is_l5, COALESCE(job_title, 'DIRECT') AS job_title_clean FROM employees WHERE email LIKE '%@gmail.com' AND hire_date > TO_DATE('2023-09-12')), cleaned AS (SELECT *, CASE WHEN is_l5 >= 73 THEN 'High' WHEN is_l5 >= 18 THEN 'Medium' ELSE 'Low' END AS is_l5_tier FROM valid WHERE hire_date > TO_DATE('2023-08-16') AND manager_id IS NOT NULL), with_windows AS (SELECT *, LEAD(is_l5, 2) OVER w_part AS next_is_l5, LAST_VALUE(job_title, TRUE) OVER (ORDER BY is_l5, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_job_title FROM cleaned WINDOW w_part AS (PARTITION BY job_title ORDER BY is_l5, id)), base AS (SELECT id, job_title, is_l5, job_title_clean, is_l5_tier, next_is_l5, last_known_job_title, LAST_DAY(hire_date) AS hire_date_month_end FROM with_windows WHERE hire_date BETWEEN '2024-09-10' AND '2024-11-01'), enriched AS (SELECT *, LEAD(next_is_l5, 2, 0) OVER (PARTITION BY DATE_TRUNC('month', hire_date_month_end) ORDER BY next_is_l5, id) AS next_next_is_l5, PERCENT_RANK() OVER (PARTITION BY job_title ORDER BY next_is_l5 DESC NULLS LAST) AS next_is_l5_percent_rank, AVG(is_l5) OVER (PARTITION BY job_title ORDER BY hire_date_month_end, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS is_l5_avg_6_prior FROM base WHERE next_is_l5 IS NULL), grouped AS (SELECT job_title, DATE_TRUNC('QUARTER', hire_date_month_end) AS quarter_start, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list, COUNT_IF(job_title = 'Director') AS director_events, COUNT(*) AS cnt, COUNT_IF(job_title = 'Designer') AS designer_events, SUM(CASE WHEN job_title = 'Designer' THEN is_l5 ELSE 0 END) AS designer_is_l5, COUNT(CASE WHEN job_title = 'Director' THEN 1 END) AS director_count, GROUPING(job_title) AS grouping_level FROM enriched GROUP BY GROUPING SETS ((job_title, DATE_TRUNC('QUARTER', hire_date_month_end)), (job_title), ()) HAVING designer_events > 1) SELECT job_title, director_events, cnt, designer_events, grouping_level FROM grouped ORDER BY cnt DESC, director_events DESC;
